import {esc,fmt} from '../../ui/format.js';
import {PHASE_TYPES,nativePhases,demandWarnings} from '../../core/native-phases.js';
export function phaseSummary(n,cycle,model) {
 if(!['operation','inspection','transport'].includes(n.type))return '';
 const native=nativePhases(n);
 return `<section class="phase-summary"><h3>Faze om–mașină</h3>${model?demandWarnings(model,n).map(w=>`<div class="notice">${esc(w)}</div>`).join(''):''}${n.phases?`<ol>${n.phases.map(p=>`<li><b>${esc(p.name)}</b> · ${esc(PHASE_TYPES[p.kind]||p.kind)} · ${fmt(native?p.duration.value:cycle*p.fraction)} s ${native?`· ${esc(p.distribution.type)} · ${esc(p.duration.provenance)}`:''}</li>`).join('')}</ol>`:'<p>Ciclu unic legacy: resurse rezervate integral.</p>'}<p class="small">${native?'Durate independente per fază; ciclul și variația globală nu scalează fazele. Resursele tehnice alocate operației sunt rezervate pe secvență; resursele fazelor se eliberează la fiecare tranziție.':'Compatibilitate legacy: ciclul total scalează proporțiile. Editarea în noul editor activează explicit semantica nativă.'}</p><button type="button" data-action="edit-phases">Configurează fazele</button>${n.phases?'<button type="button" data-action="clear-phases">Revino la ciclu unic</button>':''}</section>`;
}
export function phaseRow(p,index,pools=[]) {
 const d=p.duration||{value:p.seconds||1,provenance:'ASSUMPTION',note:''};
 const distribution=p.distribution||{type:'constant',relativeHalfRange:0};
 return `<fieldset data-phase-row="${index}"><legend>Fază</legend><label>Nume<input name="phase-name-${index}" value="${esc(p.name)}" maxlength="100" required></label><label>Tip<select name="phase-kind-${index}">${Object.entries(PHASE_TYPES).map(([id,label])=>`<option value="${id}" ${p.kind===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Durată nominală (s)<input name="phase-seconds-${index}" type="number" min="0.01" max="86400" step="any" value="${d.value}" required></label><label>Distribuție<select name="phase-distribution-${index}">${['constant','uniform'].map(type=>`<option ${type===distribution.type?'selected':''}>${type}</option>`).join('')}</select></label><label>Semilățime relativă uniformă (ratio; 0 pentru constant)<input name="phase-range-${index}" type="number" min="0" max="0.9" step="any" value="${distribution.relativeHalfRange}" required></label><label>Proveniență<select name="phase-provenance-${index}">${['MEASURED','SPEC','ASSUMPTION'].map(type=>`<option ${type===d.provenance?'selected':''}>${type}</option>`).join('')}</select></label><label>Sursă / ipoteză (durată și distribuție)<input name="phase-note-${index}" value="${esc(d.note)}" required></label><label><input type="checkbox" name="phase-inherit-${index}" ${p.inheritPeople?'checked':''}> Include personalul direct/moștenit al operației (nu în automatic)</label><details><summary>Resurse suplimentare per fază · cantități (0 = fără rezervare)</summary>${pools.filter(n=>['machine','robot','tool','hardware','sensor','software','person','team','utility'].includes(n.type)).map(n=>`<label>${esc(n.name)}<input name="phase-resource-${index}-${esc(n.id)}" type="number" min="0" max="1000" step="1" value="${p.resources?.find(r=>r.resourceId===n.id)?.quantity||0}" required></label>`).join('')}</details><div class="row"><button type="button" data-phase-up>↑ Mută înainte</button><button type="button" data-phase-down>↓ Mută după</button><button type="button" data-phase-remove>Elimină faza</button></div></fieldset>`;
}
